#[derive(Clone,Copy,Default,Debug,PartialEq,Eq)]pub struct Frame{pub frame_us:u32,pub draw_calls:u32,pub dirty_pixels:u32,pub pool_used:u32,pub static_ram:u32}
#[derive(Default)]pub struct Profiler{current:Frame,peak:Frame,frames:u64,total_us:u64}
impl Profiler{pub fn begin(&mut self,static_ram:u32){self.current=Frame{static_ram,..Frame::default()}}pub fn draw(&mut self,pixels:u32){self.current.draw_calls=self.current.draw_calls.saturating_add(1);self.current.dirty_pixels=self.current.dirty_pixels.saturating_add(pixels)}pub fn pool_used(&mut self,n:u32){self.current.pool_used=n}pub fn end(&mut self,frame_us:u32)->Frame{self.current.frame_us=frame_us;self.frames+=1;self.total_us+=frame_us as u64;self.peak.frame_us=self.peak.frame_us.max(frame_us);self.peak.draw_calls=self.peak.draw_calls.max(self.current.draw_calls);self.peak.dirty_pixels=self.peak.dirty_pixels.max(self.current.dirty_pixels);self.peak.pool_used=self.peak.pool_used.max(self.current.pool_used);self.peak.static_ram=self.peak.static_ram.max(self.current.static_ram);self.current}pub fn peak(&self)->Frame{self.peak}pub fn average_frame_us(&self)->u32{if self.frames==0{0}else{(self.total_us/self.frames)as u32}}}
